insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 19, 'Voltou, pois, a haver divisão entre os judeus, por causa dessas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 20, 'E muitos deles diziam: Ele tem demônio, e está fora de si; para que o ouvis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 21, 'Outros diziam: Estas palavras não são de um endemoninhado; por acaso pode um demônio dar vista aos cegos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 22, 'E era a festa da renovação [do Templo] em Jerusalém, e era inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 23, 'E andava Jesus passeando no Templo, na entrada de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 24, 'Rodearam-no, então, os Judeus, e lhe disseram: Até quando farás nossa alma em dúvida? Se tu és o Cristo, dize-nos abertamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 25, 'Respondeu-lhes Jesus: Já vos tenho dito, e não credes. As obras que eu faço em nome de meu Pai, essas testemunham de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 26, 'Mas vós não credes, porque não sois de minhas ovelhas, como já vos tenho dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 27, 'Minhas ovelhas ouvem minha voz, e eu as conheço, e elas me seguem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 28, 'E eu lhes dou a vida eterna, e para sempre não perecerão, e ninguém as arrancará de minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 29, 'Meu Pai, que [as] deu para mim, é maior que todos; e ninguém pode arrancá-las da mão de meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 30, 'Eu e o Pai somos um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 31, 'Voltaram pois os Judeus a tomar pedras para o apedrejarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 32, 'Respondeu-lhes Jesus: Muitas boas obras de meu Pai vos tenho mostrado; por qual obra destas me apedrejais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 33, 'Responderam-lhe os judeus dizendo: Por boa obra não te apedrejamos, mas pela blasfêmia; e porque sendo tu homem, a ti mesmo te fazes Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 34, 'Respondeu-lhes Jesus: Não está escrito em vossa Lei: Eu disse: Sois deuses?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 35, 'Pois se [a Lei] chamou deuses a aqueles, para quem a palavra de Deus foi feita, (e a Escritura não pode ser quebrada);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 36, '[A mim] ,a quem o Pai santificou, e ao mundo enviou, dizeis vós: Blasfemas; porque disse: Sou Filho de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 37, 'Se não faço as obras de meu Pai, não creiais em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 38, 'Porém se eu as faço, e não credes em mim, crede nas obras; para que conheçais e creiais que o Pai está em mim, e eu nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 39, 'Então procuravam outra vez prendê-lo; e ele saiu de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 40, 'E voltou a ir para o outro lado do Jordão, ao lugar onde João primeiro batizava; e ficou ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 41, 'E muitos vinham a ele, e diziam: Em verdade que nenhum sinal fez João; mas tudo quanto João disse deste era verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 42, 'E muitos ali creram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 1, 'E estava doente um certo Lázaro, de Betânia, a aldeia de Maria e de sua irmã Marta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 2, '(E era Maria a que ungiu ao Senhor com o óleo, e com seus cabelos lhe limpou os pés; [a que] cujo irmão Lázaro era o que estava doente).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 3, 'Enviaram pois suas irmãs [uma mensagem] a ele, dizendo: Senhor, eis que aquele a quem [tu] amas está doente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 4, 'E ouvindo Jesus, disse: Esta doença não é para morte, mas para glória de Deus; para que o Filho de Deus seja por ela glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 5, 'E Jesus amava a Marta, e a sua irmã, e a Lázaro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 6, 'Quando, pois, ele ouviu que estava doente, ficou ainda dois dias no lugar onde estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 7, 'Então depois disto voltou a dizer aos discípulos: Vamos outra vez à Judeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 8, 'Disseram-lhe os discípulos: Rabi, ainda agora os Judeus procuravam te apedrejar; e tu voltas novamente para lá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 9, 'Respondeu Jesus: Não há doze horas no dia? Se alguém anda de dia, não tropeça, porque vê a luz deste mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 10, 'Mas se alguém anda de noite, tropeça; porque nele não há luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 11, 'Ele falou estas coisas; e depois disto, disse-lhes: Lázaro, nosso amigo, dorme; mas vou para despertá-lo do sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 12, 'Disseram pois seus discípulos: Senhor, se [ele] dorme, será salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 13, 'Mas Jesus dizia [isto] de sua morte; porém eles pensavam que falava do repouso do sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 14, 'Então pois lhes disse Jesus claramente: Lázaro está morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 15, 'E me alegro, por causa de vós, que eu não estivesse lá, para que creiais; porém vamos até ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 16, 'Disse pois Tomé, chamado o Dídimo, aos colegas discípulos: Vamos nós também, para que com ele morramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 17, 'Vindo pois Jesus, encontrou que já havia quatro dias que estava na sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 18, '(E Betânia era como quase quinze estádios de Jerusalém).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 19, 'E muitos dos judeus tinham vindo até Marta e Maria, para consolá-las por seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 20, 'Ouvindo pois Marta que Jesus vinha, saiu-lhe ao encontro; mas Maria ficou sentada em casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 21, 'Disse pois Marta a Jesus: Senhor, se tu estivesses aqui, meu irmão não teria morrido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 22, 'Porém também sei agora, que tudo quanto pedires a Deus, Deus o dará a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 23, 'Disse-lhe Jesus: Teu irmão ressuscitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 24, 'Marta lhe disse: Eu sei que ele ressuscitará, na ressurreição, no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 25, 'Disse-lhe Jesus: Eu sou a ressurreição, e a vida; quem crê em mim, ainda que esteja morto, viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 26, 'E todo aquele que vive, e crê em mim, para sempre não morrerá. Crês nisto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 27, 'Disse-lhe ela: Sim, Senhor; já cri que tu és o Cristo, o Filho de Deus, que viria ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 28, 'E dito isto, [ela] se foi, e chamou em segredo a Maria, sua irmã, dizendo: Aqui está o Mestre, e ele te chama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 29, 'Ouvindo ela [isto] ,logo se levantou, e foi até ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 30, '(Porque Jesus ainda não havia chegado à aldeia; mas estava no lugar onde Marta lhe saíra ao encontro).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 31, 'Vendo pois os judeus que com ela estavam em casa, e a consolavam, que Maria com pressa se levantara, e saíra, seguiram-na, dizendo: Ela vai para a sepultura, para chorar lá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 32, 'Vindo pois Maria aonde Jesus estava, e vendo-o, caiu a seus pés, dizendo-lhe: Senhor, se tu estivesses aqui, meu irmão não teria morrido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 33, 'Quando Jesus a viu chorar, e aos judeus, que vinham chorando com ela, comoveu-se em espírito, e ficou perturbado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 34, 'E disse: Onde o pusestes? Disseram-lhe: Senhor, vem, e vê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 35, 'Jesus chorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 36, 'Disseram pois os Judeus: Vede como ele o amava!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 37, 'E alguns deles disseram: Não podia este, que abriu os olhos ao cego, ter feito também que este não morresse?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 38, 'Comovendo-se pois Jesus outra vez em si mesmo, veio à sepultura; e era [esta] uma caverna, e estava uma pedra posta sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 39, 'Disse Jesus: Tirai a pedra. Marta, a irmã do morto, disse-lhe: Senhor, já cheira mal, porque já é de quatro dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 40, 'Jesus disse-lhe: Não te disse, que se creres, verás a glória de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 41, 'Tiraram, pois, a pedra de onde o morto jazia. E Jesus levantou os olhos para cima, e disse: Pai, graças te dou, porque me tens ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 42, 'Porém eu bem sabia que sempre me ouves; mas por causa da multidão, que está ao redor, [assim] disse; para que creiam que tu me enviaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 43, 'E havendo dito isto, clamou com grande voz: Lázaro, sai fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 44, 'E o que estava morto saiu, [com] as mãos e os pés atados, e seu rosto envolto em um lenço. Disse-lhes Jesus: Desatai-o, e deixai-o ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 45, 'Pelo que, muitos dos Judeus, que tinham vindo a Maria, e haviam visto o que Jesus fizera, creram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 46, 'Mas alguns deles foram aos fariseus, e lhes disseram o que Jesus havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 47, 'Então os sacerdotes e os fariseus juntaram o supremo conselho, e disseram: Que faremos? Porque este homem faz muitos sinais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 48, 'Se assim o deixamos, todos crerão nele, e virão os romanos, e nos tomarão tanto o lugar quanto a nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 49, 'E Caifás, um deles, que era sumo sacerdote daquele ano, lhes disse: Vós nada sabeis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 50, 'Nem considerais que nos convém, que um homem morra pelo povo, e toda a nação não pereça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 51, 'E ele não disse isto de si mesmo; mas que, como era o sumo sacerdote daquele ano, profetizou que Jesus morreria pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 52, 'E não somente por aquele povo, mas também para que juntasse em um aos filhos de Deus, que estavam dispersos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 53, 'Então desde aquele dia se aconselhavam juntos para o matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 54, 'De maneira que Jesus já não andava mais abertamente entre os judeus, mas foi-se dali para a terra junto ao deserto, a uma cidade chamada Efraim; e ali andava com seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 55, 'E estava perto a páscoa dos judeus, e muitos daquela terra subiram a Jerusalém antes da páscoa, para se purificarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 56, 'Buscavam pois a Jesus, e diziam uns aos outros estando no Templo: Que vos parece? Que ele não virá à festa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 11, 57, 'E os sacerdotes e os fariseus tinham dado ordem de que, se alguém soubesse onde ele estava, o denunciasse, para que o pudessem prender.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 1, 'Veio, pois, Jesus seis dias antes da páscoa a Betânia, onde estava Lázaro, o que havia morrido, a quem ressuscitara dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 2, 'Fizeram-lhe, pois, ali uma ceia, e Marta servia; e Lázaro era um dos que juntamente com ele estavam sentados [à mesa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 3, 'Tomando então Maria um arrátel de óleo perfumado de nardo puro, de muito preço, ungiu os pés de Jesus, e limpou os pés dele com seus cabelos; e encheu-se a casa do cheiro do óleo perfumado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 4, 'Então disse Judas de Simão Iscariotes, um de seus discípulos, o que o trairia:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 5, 'Por que se não vendeu este óleo perfumado por trezentos dinheiros, e se deu aos pobres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 6, 'E isto disse ele, não pelo cuidado que tivesse dos pobres; mas porque era ladrão, e tinha a bolsa, e trazia o que se lançava [nela] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 7, 'Disse pois Jesus: Deixa-a; para o dia de meu sepultamento guardou isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 8, 'Porque aos pobres sempre os tendes convosco; porém a mim não me tendes sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 9, 'Muita gente dos judeus soube pois, que ele estava ali; e vieram, não somente por causa de Jesus, mas também para verem a Lázaro, a quem ressuscitara dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 10, 'E os chefes dos sacerdotes se aconselharam de também matarem a Lázaro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 11, 'Porque muitos dos judeus iam por causa dele, e criam em Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 12, 'No dia seguinte, ouvindo uma grande multidão, que viera à festa, que Jesus vinha a Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 13, 'Tomaram ramos de plantas e lhe saíram ao encontro, e clamavam: Hosana! Bendito aquele que vem no nome do Senhor, o Rei de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 14, 'E Jesus achou um jumentinho, e sentou-se sobre ele, como está escrito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 15, 'Não temas, ó filha de Sião; eis que teu Rei vem sentado sobre o filhote de uma jumenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 16, 'Porém seus discípulos não entenderam isto ao princípio; mas sendo Jesus já glorificado, então se lembraram que isto dele estava escrito, e [que] isto lhe fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 17, 'A multidão pois, que estava com ele, testemunhava, que a Lázaro chamara da sepultura, e o ressuscitara dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 18, 'Pelo que também a multidão lhe saiu ao encontro, porque ouvira que fizera este sinal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 19, 'Disseram pois os fariseus entre si: Vedes que nada aproveitais? Eis que o mundo vai após ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 20, 'E havia alguns gregos dos que haviam subido para adorarem na festa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 21, 'Estes pois vieram a Filipe, que era de Betsaida de Galileia, e rogaram-lhe, dizendo: Senhor, queríamos ver a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 22, 'Veio Filipe, e disse-o a André; e André então e Filipe o disseram a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 23, 'Porém Jesus lhes respondeu, dizendo: Chegada é a hora em que o Filho do homem será glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 24, 'Em verdade, em verdade vos digo, se o grão de trigo, ao cair na terra, não morrer, ele fica só; porém se morrer, dá muito fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 25, 'Quem ama sua vida a perderá; e quem neste mundo odeia sua vida, a guardará para a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 26, 'Se alguém me serve, siga-me; e onde eu estiver, ali estará também meu servo. E se alguém me servir, o Pai o honrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 27, 'Agora minha alma está perturbada; e que direi? Pai, salva-me desta hora; mas por isso vim a esta hora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 28, 'Pai, glorifica teu Nome. Veio, pois, uma voz do céu, [que dizia] : E já [o] tenho glorificado, e outra vez [o] glorificarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 29, 'A multidão pois que ali estava, e [a] ouviu, dizia que havia sido trovão. Outros diziam: Algum anjo falou com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 30, 'Respondeu Jesus e disse: Esta voz não veio por causa de mim, mas sim por causa de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 31, 'Agora é o juízo deste mundo; agora será lançado fora o príncipe deste mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 32, 'E eu, quando for levantado da terra, trarei todos a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 33, '(E isto dizia, indicando de que morte [ele] morreria.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 34, 'Respondeu-lhe a multidão: Temos ouvido da Lei que o Cristo permanece para sempre; e como tu dizes que convém que o Filho do homem seja levantado? Quem é este Filho do homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 35, 'Disse-lhes pois Jesus: Ainda por um pouco de tempo a luz está convosco; andai enquanto tendes luz, para que as trevas vos não apanhem. E quem anda em trevas não sabe para onde vai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 36, 'Enquanto tendes luz, crede na luz, para que sejais filhos da luz.Estas coisas falou Jesus, e indo-se, escondeu-se deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 37, 'E ainda que perante eles tinha feito tantos sinais, não criam nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 38, 'Para que se cumprisse a palavra do profeta Isaías, que disse: Senhor, quem creu em nossa pregação? E a quem o braço do Senhor foi revelado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 39, 'Por isso não podiam crer, porque outra vez Isaías disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 40, 'Os olhos lhes cegou, e o coração lhes endureceu; para não acontecer que vejam dos olhos, e entendam do coração, e se convertam, e eu os cure.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 41, 'Isto disse Isaías, quando viu sua glória, e falou dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 42, 'Contudo ainda até muitos dos chefes também creram nele; mas não o confessavam por causa dos fariseus; para não serem expulsos da sinagoga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 43, 'Porque amavam mais a glória humana do que a glória de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 44, 'E exclamou Jesus, e disse: Quem crê em mim, não crê [somente] em mim, mas [também] naquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 45, 'E quem vê a mim, vê a aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 46, 'Eu sou a luz que vim ao mundo, para que todo aquele que crê em mim, não permaneça em trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 47, 'E se alguém ouvir minhas palavras, e não crer, eu não o julgo; porque não vim para julgar o mundo, mas sim para salvar o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 48, 'Quem me rejeitar e não receber minhas palavras, já tem quem o julgue: a palavra que eu tenho falado, essa o julgará no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 49, 'Porque eu não tenho falado de mim mesmo; porém o Pai que me enviou, ele me deu mandamento do que devo dizer, e do que devo falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 12, 50, 'E sei que seu mandamento é vida eterna. Portanto o que eu falo, falo assim como o Pai tem me dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 1, 'E antes da festa da páscoa, sabendo Jesus que sua hora já era vinda, para que deste mundo passasse para o Pai, havendo amado aos seus, que estavam no mundo, até o fim os amou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 2, 'E terminada a ceia, o diabo já havia metido no coração de Judas de Simão Iscariotes, que o traísse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 3, 'Sabendo Jesus que o Pai já tinha lhe dado todas as coisas nas mãos, e que ele era vindo de Deus, e para Deus ele iria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 4, 'Levantou-se da ceia, e tirou as roupas, e tomando uma toalha, envolveu- [a] em si;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 5, 'Depois pôs água em uma bacia, e começou a lavar os pés dos discípulos, e limpá-los com a toalha com que estava envolto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 6, 'Veio, pois, a Simão Pedro; e ele lhe disse: Senhor, tu a mim lavas meus pés?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 7, 'Respondeu Jesus, e disse-lhe: O que eu faço tu não o sabes agora; mas depois o entenderás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 8, 'Disse-lhe Pedro: Nunca lavarás meus pés. Respondeu-lhe então Jesus: Se eu não te lavar, não tens parte comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 9, 'Disse-lhe Simão Pedro: Senhor, [lava] não só meus pés, mas também as mãos e a cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 10, 'Disse-lhe Jesus: Aquele que está lavado não necessita lavar, a não ser os pés, mas está todo limpo. E vós limpos estais, porém não todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 11, 'Porque ele bem sabia quem o trairia; por isso disse: Nem todos estais limpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 12, 'Quando então, tendo eles lavado os pés, e tomado suas roupas, voltou a se sentar [à mesa] ,e disse-lhes: Entendeis o que vos tenho feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 13, 'Vós me chamais Mestre, e Senhor, e bem dizeis; que eu o sou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 14, 'Pois se eu, o Senhor, e o Mestre, tenho lavado vossos pés, também vós deveis lavar vossos pés uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 15, 'Porque vos tenho dado exemplo, para que como eu vos tenho feito, façais vós também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 16, 'Em verdade, em verdade vos digo, [que] o servo não é maior que seu senhor; nem enviado maior que aquele que o enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 17, 'Se sabeis estas coisas, sereis bem-aventurados se as fizerdes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 18, 'Não digo de todos; bem sei eu aos que tenho escolhido; mas para que se cumpra a Escritura, [que diz] : O que come comigo, levantou contra mim seu calcanhar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 19, 'Desde agora, antes que se faça, digo-o a vós, para que, quando se fizer, creiais que eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 20, 'Em verdade, em verdade vos digo, [que] se alguém receber ao [que] eu enviar, a mim me recebe; e quem a mim me receber, recebe a aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 21, 'Havendo Jesus dito isto, perturbou-se em espírito, e testemunhou, e disse: Em verdade, em verdade vos digo, que um de vós me trairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 22, 'Pelo que os discípulos se olhavam uns para os outros, duvidando de quem ele dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 23, 'E um dos discípulos, a quem Jesus amava, estava sentado [à mesa encostado] no seio de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 24, 'A este pois fez sinal Simão Pedro, que perguntasse quem era aquele de quem ele dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 25, 'E declinando-se ele ao peito de Jesus, disse-lhe: Senhor, quem é?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 26, 'Respondeu Jesus: Aquele a quem eu der o pedaço molhado de pão. E molhando o pedaço de pão, deu-o a Judas de Simão Iscariotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 27, 'E após o pedaço de pão, entrou nele Satanás. Disse-lhe pois Jesus: O que fazes, faze-o depressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 28, 'E nenhum dos que estavam sentados [à mesa] entendeu para que ele lhe dissera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 29, 'Pois alguns pensavam que, porque Judas tinha a bolsa, Jesus havia lhe dito: Compra o que para o que nos é necessário para a festa; ou que alguma coisa desse aos pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 30, 'Havendo ele pois tomado o pedaço de pão, logo saiu. E já era noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 31, 'Tendo, pois, ele saído, disse Jesus: Agora o Filho do homem é glorificado, e Deus é glorificado nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 32, 'Se Deus nele é glorificado, também Deus o glorificará em si mesmo, e logo o glorificará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 33, 'Filhinhos, ainda um pouco estou convosco. Vós me buscareis; e tal como eu aos Judeus: Para onde eu vou, vós não podeis vir; assim também o digo a vós agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 34, 'Um novo mandamento vos dou: que vos ameis uns aos outros; tal como eu vos amei, também ameis vós uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 35, 'Nisto todos conhecerão que sois meus discípulos: se vós tiverdes amor uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 36, 'Disse-lhe Simão Pedro: Senhor, para onde vais? Respondeu-lhe Jesus: Para onde eu vou tu não podes me seguir agora; porém depois me seguirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 37, 'Disse-lhe Pedro: Senhor, por que agora não posso te seguir? Por ti eu darei minha vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 13, 38, 'Respondeu-lhe Jesus: Por mim darás tua vida? Em verdade, em verdade te digo, que o galo não cantará, até que três vezes me negues.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 1, 'Não se perturbe vosso coração; credes em Deus, crede também em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 2, 'Na casa de meu Pai há muitas moradas; senão, eu vos diria; vou para vos preparar lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 3, 'E quando eu for, e vos preparar lugar, outra vez virei, e vos tomarei comigo, para que vós também estejais onde eu estiver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 4, 'E já sabeis para onde vou, e sabeis o caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 5, 'Disse-lhe Tomé: Senhor, não sabemos para onde vais; e como podemos saber o caminho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 6, 'Jesus lhe disse: Eu sou o caminho, e a verdade, e a vida. Ninguém vem ao Pai, a não ser por mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 7, 'Se vós conhecêsseis a mim, também conheceríeis a meu Pai; e desde agora já o conheceis, e o tendes visto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 8, 'Disse-lhe Filipe: Senhor, mostra-nos ao Pai, e basta-nos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 9, 'Jesus lhe disse: Tanto tempo [há que] estou convosco, e [ainda] não me tens conhecido, Filipe? Quem a mim tem visto, já tem visto ao Pai; e como dizes tu: Mostra-nos ao Pai?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 10, 'Não crês tu que eu [estou] no Pai, e que o Pai está em mim? As palavras que eu vos falo, não as falo de mim mesmo, mas o Pai que está em mim, ele [é o que] faz as obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 11, 'Crede em mim que eu [estou] no Pai, e [que] o Pai está em mim; e quando não, crede em mim por causa das próprias obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 12, 'Em verdade, em verdade vos digo, que aquele que crê em mim, as obras que eu faço também ele as fará; e fará maiores que estas. Porque eu vou a meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 13, 'E tudo quanto pedirdes em meu nome, eu o farei; para que o Pai seja glorificado no Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 14, 'Se alguma coisa pedirdes em meu nome, eu [a] farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 15, 'Se me amais, guardai meus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 16, 'E eu rogarei ao Pai, e ele vos dará outro Consolador, para que fique sempre convosco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 17, 'Ao Espírito de verdade, a quem o mundo não pode receber; porque não o vê, nem o conhece; mas vós o conheceis, porque habita convosco, e estará em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 18, 'Não vos deixarei órfãos; eu virei a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 19, 'Ainda um pouco, e o mundo não me verá mais; mas vós me vereis; porque eu vivo, e vós vivereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 20, 'Naquele dia conhecereis que [estou] em meu Pai, e vós em mim, e eu em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 21, 'Quem tem meus mandamentos, e os guarda, esse é o que me ama; e quem a mim me ama, será amado de meu Pai, e eu o amarei, e a ele me manifestarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 22, 'Disse-lhe Judas (não o Iscariotes): Senhor, que há, porque a nós te manifestarás, e não ao mundo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 23, 'Respondeu Jesus, e disse-lhe: Se alguém me ama, guardará minha palavra, e meu Pai o amará, e viremos a ele, e faremos morada com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 24, 'Quem não me ama, não guarda minhas palavras. E a palavra que ouvis não é minha, mas sim do Pai que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 25, 'Estas coisas tenho dito a vós, estando [ainda] convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 26, 'Mas aquele Consolador, o Espírito Santo, ao qual o Pai enviará em meu nome, esse vos ensinará tudo, e tudo quanto tenho dito vós, [ele] vos fará lembrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 27, 'A paz vos deixo, minha paz vos dou; vou dá- [la] a vós, não como o mundo [a] dá. Não se perturbe vosso coração, nem se atemorize.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 28, 'Já ouvistes que vos tenho dito: Vou, e venho a vós. Se me amásseis, verdadeiramente vos alegraríeis, porque tenho dito: Vou ao Pai; pois meu Pai maior é que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 29, 'E já agora o disse a vós antes que aconteça, para que quando acontecer, [o] creiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 30, 'Já não falarei muito convosco; pois o príncipe deste mundo já vem, e ele nada tem em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 14, 31, 'Mas para que o mundo saiba que eu amo ao Pai, e assim faço como o Pai me mandou; levantai-vos, vamos embora daqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 1, 'Eu sou a videira verdadeira, e meu Pai é o lavrador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 2, 'Todo ramo que em mim não dá fruto, ele o tira; e todo o que da fruto, ele o limpa, para que dê mais fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 3, 'Vós já estais limpos pela palavra que vos tenho falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 4, 'Estai em mim, e eu em vós; como o ramo de si mesmo não pode dar fruto, se não estiver na videira, assim vós também não, se não estiverdes em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 5, 'Eu sou a videira, vós [sois] os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 6, 'Se alguém não estiver em mim, é lançado fora, como o ramo, e seca-se; e os colhem , e os lançam no fogo, e ardem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 7, 'Se vós estiverdes em mim, e minhas palavras estiverem em vós, tudo o que quiserdes pedireis, e será feito para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 8, 'Nisto é glorificado meu Pai, em que deis muito fruto; e [assim] sereis meus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 9, 'Como o Pai me amou, também eu vos amei; estai neste meu amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 10, 'Se guardardes meus mandamentos, estareis em meu amor. Como eu tenho guardado os mandamentos de meu Pai, e estou em seu amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 11, 'Estas coisas eu tenho vos dito para que minha alegria esteja em vós, e vossa alegria seja completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 12, 'Este é meu mandamento: que vos ameis uns aos outros, assim como eu vos amei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 13, 'Ninguém tem maior amor que este: que alguém ponha sua vida por seus amigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 14, 'Vós sois meus amigos, se fizerdes o que eu vos mando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 15, 'Já não vos chamo mais servos; porque o servo não sabe o que faz seu senhor; mas eu tenho vos chamado de amigos, porque tudo quanto ouvi de meu Pai eu tenho vos feito conhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 16, 'Não [fostes] vós [que] me escolhestes, porém eu vos escolhi, e tenho vos posto para que vades, e deis fruto, e vosso fruto permaneça; para que tudo quanto pedirdes ao Pai em meu nome, ele vos dê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 17, 'Isto vos mando, para que vos ameis uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 18, 'Se o mundo vos odeia, sabei que odiou a mim antes que a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 19, 'Se vós fôsseis do mundo, o mundo amaria ao seu; mas porque não sois do mundo, antes eu vos escolhi do mundo, por isso o mundo vos odeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 20, 'Lembrai-vos da palavra que vos tenho dito: não é o servo maior que seu senhor. Se me perseguiram, também vos perseguirão; se guardaram minha palavra, também guardarão a vossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 21, 'Mas tudo isto vos farão por causa do meu nome; porque não conhecem a aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 22, 'Se eu não tivesse vindo, nem lhes houvesse falado, não teriam pecado; mas agora já não têm pretexto pelo seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 23, 'Quem me odeia, também odeia a meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 24, 'Se eu entre eles não tivesse feito obras, que nenhum outro fizera, não teriam pecado; mas agora as viram, e [contudo] odiaram a mim, e a meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 25, 'Mas [isto é] para que se cumpra a palavra que está escrita em sua Lei: Sem causa me odiaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 26, 'Mas quando vier o Consolador, que eu do Pai vos enviarei, aquele Espírito de verdade, que sai do Pai, ele testemunhará de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 15, 27, 'E também vós testemunhareis, pois estivestes comigo desde o princípio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 1, 'Estas coisas tenho vos dito para que não tropeceis na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 2, 'Expulsarão a vós das sinagogas; mas a hora vem, quando qualquer que vos matar, pensará fazer serviço a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 3, 'E estas coisas vos farão, porque nem ao Pai, nem a mim me conheceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 4, 'Porém tenho vos dito isto para que, quando aquela hora vier, disso vos lembreis, que já o dissera a vós; mas isto eu não vos disse desde o princípio, porque eu estava convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 5, 'E agora vou para aquele que me enviou; e nenhum de vós me pergunta: Para onde vais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 6, 'Porém, porque vos disse estas coisas, a tristeza encheu vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 7, 'Mas vos digo a verdade, que vos convém que eu vá; porque se eu não for, o Consolador não virá a vós; porém se eu for, eu o enviarei a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 8, 'E vindo ele, convencerá ao mundo do pecado, e da justiça, e do juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 9, 'Do pecado, porque não creem em mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 10, 'E da justiça, porque vou para meu Pai, e não me vereis mais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 11, 'E do juízo, porque o Príncipe deste mundo já está julgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 12, 'Ainda tenho muitas coisas que vos dizer, mas agora [ainda] não podeis suportá-las.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 13, 'Porém quando vier aquele Espírito de verdade, ele vos guiará em toda verdade. Porque de si mesmo não falará; mas falará tudo o que ouvir; E ele vos anunciará as coisas que virão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 14, 'Ele me glorificará, porque tomará do [que é] meu, e vos anunciará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 15, 'Tudo quanto tem o Pai é meu; por isso eu disse, que tomará do [que é] meu, e vos anunciará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 16, 'Um pouco, e não me vereis; e mais um pouco, e me vereis; porque vou ao Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 17, 'Disseram pois [alguns] de seus discípulos uns aos outros: Que é isto que ele nos diz: Um pouco, e não me vereis; e mais um pouco, e me vereis; e porque vou ao Pai?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 18, 'Então diziam: Que é isto que ele diz? Um pouco? Não sabemos o que diz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 19, 'Conheceu pois Jesus que lhe queriam perguntar, e disse-lhes: Perguntais entre vós sobre isto que disse: Um pouco, e não me vereis; e mais um pouco, e me vereis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 20, 'Em verdade, em verdade vos digo, que vós chorareis, e lamentareis, e o mundo se alegrará, e vós estareis tristes; mas vossa tristeza se tornará em alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 21, 'A mulher quando está no parto tem tristeza, porque sua hora é vinda; mas havendo nascido a criança, já não se lembra da aflição, pela alegria de um homem ter nascido no mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 22, 'Assim também vós agora na verdade tendes tristeza; mas novamente vos verei, e vosso coração se alegrará, e ninguém tirará vossa alegria de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 23, 'E naquele dia nada me perguntareis. Em verdade, em verdade vos digo, que tudo quanto pedirdes a meu Pai em meu nome, ele vos dará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 24, 'Até agora nada pedistes em meu nome; pedi, e recebereis, para que vossa alegria seja completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 25, 'Estas coisas vos falei por parábolas; porém a hora vem quando não mais vos falarei por parábolas; mas vos falarei abertamente sobre o Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 26, 'Naquele dia pedireis em meu nome; e não vos digo, que eu suplicarei ao Pai por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 27, 'Pois o próprio Pai vos ama, porque vós me amastes, e crestes que eu saí de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 28, 'Saí do Pai, e vim ao mundo; novamente deixo o mundo, e vou ao Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 29, 'Disseram-lhe seus Discípulos: Eis que agora falas abertamente, e nenhuma parábola dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 30, 'Agora sabemos que sabes todas as coisas; e não necessitas que ninguém te pergunte. Por isso cremos que saíste de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 31, 'Respondeu-lhes Jesus: Agora credes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 32, 'Eis que a hora vem, e já é chegada, quando sereis dispersos, cada um por si, e me deixareis só. Porém não estou só, porque o Pai está comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 16, 33, 'Estas coisas tenho vos dito para que tenhais paz em mim; no mundo tereis aflição; mas tende bom ânimo; eu venci o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 1, 'Jesus falou estas coisas, levantou seus olhos ao céu, e disse: Pai, chegada é a hora; glorifica a teu Filho, para que também teu Filho glorifique a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 2, 'Assim como lhe deste poder sobre toda carne, para que a todos quantos lhe deste, lhes dê a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 3, 'E esta é a vida eterna: que conheçam a ti, o único Deus verdadeiro, e a Jesus Cristo, a quem tens enviado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 4, 'Eu já te glorifiquei na terra; consumado tenho a obra que me deste para eu fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 5, 'E agora glorifica-me tu, ó Pai, junto de ti mesmo, com aquela glória que eu tinha junto de ti, antes que o mundo existisse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 6, 'Manifestei teu nome aos seres humanos que me deste do mundo. Eles eram teus, e tu os deste a mim; e eles guardaram tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 7, 'Agora eles sabem que tudo quanto me deste vem de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 8, 'Porque as palavras que tu me deste eu lhes dei; e eles [as] receberam, e verdadeiramente reconheceram que eu saí de ti, e creram que tu me enviaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 9, 'Eu rogo por eles; não rogo pelo mundo, mas sim por aqueles que tu me deste, porque são teus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 10, 'E todas as minhas coisas são tuas; e as tuas coisas são minhas; e nelas sou glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 11, 'E eu já não estou no mundo; porém estes [ainda] estão no mundo, e eu venho a ti. Pai Santo, guarda-os em teu nome, a aqueles que tens me dado, para que sejam um, como nós [somos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 12, 'Quando eu com eles estava no mundo, em teu nome eu os guardava. A aqueles que tu me deste eu os tenho guardado; e nenhum deles se perdeu, a não ser o filho da perdição, para que a Escritura se cumpra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 13, 'Mas agora venho a ti, e falo isto no mundo, para que em si mesmos tenham minha alegria completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 14, 'Tua palavra lhes dei, e o mundo os odiou, porque não são do mundo, assim como eu não sou do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 15, 'Não suplico que os tires do mundo, mas que os guardes do maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 16, 'Eles não são do mundo, assim como eu não sou do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 17, 'Santifica-os em tua verdade; tua palavra é a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 18, 'Assim como tu me enviaste, eu os enviei ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 19, 'E por eles a mim mesmo me santifico, para que também eles seja santificados em verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 20, 'E não suplico somente por estes, mas também por aqueles que crerão em mim, por sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 21, 'Para que todos sejam um; como tu, Pai, em mim, e eu em ti, que também eles em nós sejam um; para que o mundo creia que tu tens me enviado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 22, 'E eu tenho lhes dado a glória que tu me deste, para que sejam um, tal como nós somos um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 23, 'Eu neles, e tu em mim; para que sejam completos em um; e para que o mundo conheça que tu me enviaste, e que tu os amaste, assim como me amaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 24, 'Pai, aqueles que tens me dado, quero que onde eu estiver, eles também estejam comigo; para que vejam minha glória, que tens me dado, pois tu me amaste desde antes da fundação do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 25, 'Pai justo, o mundo também não tem te conhecido, e estes têm conhecido que tu me enviaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 17, 26, 'E eu fiz teu nome ser conhecido por eles, e eu farei com que seja conhecido, para que o amor com que me amaste esteja neles, e eu neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 1, 'Havendo Jesus dito estas coisas, saiu com seus discípulos para além do ribeiro de Cedrom, onde havia um jardim, em que ele entrou ele, e seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 2, 'E também Judas, o que o traía, conhecia aquele lugar; porque muitas vezes se juntara ali Jesus com seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 3, 'Tendo Judas, pois, tomado a tropa e [alguns dos] oficiais dos sacerdotes e dos fariseus, veio ali com lanternas, tochas, e armas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 4, 'Sabendo pois Jesus todas as coisas que viriam sobre ele, adiantou-se, e disse-lhes: A quem buscais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 5, 'Responderam-lhe: A Jesus Nazareno. Disse-lhes Jesus: Eu sou. E Judas, o que o traía, também estava com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 6, 'Quando pois lhes disse: Eu sou, voltaram para trás, e caíram em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 7, 'Voltou pois a lhes perguntar: A quem buscais? E eles disseram: A Jesus Nazareno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 8, 'Respondeu Jesus: Já vos disse que eu sou. Portanto se buscais a mim, deixai a estes irem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 9, 'Para que se cumprisse a palavra, que tinha dito: Dos que me deste, a nenhum deles perdi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 10, 'Simão Pedro, pois, que tinha espada, puxou dela, e feriu ao servo do sacerdote, e cortou a sua orelha direita. E era o nome do servo Malco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 11, 'Disse pois Jesus a Pedro: Põe tua espada na bainha; não beberei eu o copo que o Pai tem me dado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 12, 'O grupo de soldados pois, e o comandante, e os oficiais dos judeus juntamente tomaram a Jesus, e o amarraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 13, 'E o levaram primeiramente a Anás, porque era sogro de Caifás, o qual era o sumo sacerdote daquele ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 14, 'E era Caifás o que havia aconselhado aos judeus de que convinha que um homem morresse pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 15, 'E Simão Pedro seguia a Jesus com outro discípulo. E este discípulo era conhecido do sacerdote, e entrou com Jesus no pátio do sumo sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 16, 'E Pedro estava fora à porta. Saiu pois o outro discípulo, que era conhecido do sacerdote, e falou à porteira, e pôs dentro a Pedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 17, 'Disse pois a serva porteira a Pedro: Não és tu também dos discípulos deste homem? Disse ele: Não sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 18, 'E estavam [ali] os servos, e os oficiais, que haviam feito [uma fogueira de] brasas, porque fazia frio, e se esquentavam. Estava Pedro com eles, e se esquentava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 19, 'Perguntou pois o sacerdote a Jesus sobre seus discípulos, e sobre sua doutrina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 20, 'Jesus lhe respondeu: Eu abertamente falei ao mundo; eu sempre ensinei na sinagoga e no Templo, onde os Judeus de todos os lugares se juntam, e nada falei em oculto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 21, 'Por que perguntas a mim? Pergunta aos que o ouviram, que é o que lhes falei. Eis que estes sabem que é o que tenho dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 22, 'E dizendo ele isto, um dos oficiais, que ali estava, deu a Jesus uma bofetada, dizendo: Assim respondes ao sumo sacerdote?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 23, 'Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; e se bem, por que me feres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 24, '(Pois Anás o mandara amarrado ao sumo sacerdote Caifás.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 25, 'E Simão Pedro estava ali, e se esquentava; disseram-lhe pois: Não és tu também de seus discípulos? Ele negou, e disse: Não sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 26, 'Disse um dos servos do sacerdote, parente daquele a quem Pedro cortara a orelha: Eu não te vi no jardim com ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 27, 'Pedro negou pois outra vez, e logo cantou o galo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 28, 'Levaram pois a Jesus de Caifás para o tribunal. E era pela manhã; e não entraram no tribunal, para que não se contaminassem, mas que pudessem comer a Páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 29, 'Saiu pois Pilatos até eles fora, e disse: Que acusação trazeis contra este homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 30, 'Responderam, e disseram-lhe: Se este não fosse malfeitor, não o entregaríamos a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 31, 'Disse-lhes pois Pilatos: Tomai-o vós, e julgai-o segundo vossa lei. Disseram-lhe pois os Judeus: Não nos é lícito matar a alguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 32, 'Para que se cumprisse a palavra de Jesus, que tinha dito, dando a entender de que morte havia de morrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 33, 'Então Pilatos voltou a entrar no tribunal, e chamou a Jesus, e disse-lhe: És tu o Rei dos Judeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 34, 'Respondeu-lhe Jesus: Tu dizes isso de ti mesmo, ou outros te disseram de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 35, 'Pilatos respondeu: Por acaso eu sou Judeu? Tua gente e os chefes dos sacerdotes te entregaram a mim; que fizeste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 36, 'Respondeu Jesus: Meu Reino não é deste mundo; se meu Reino fosse deste mundo, meus trabalhadores lutariam, para que eu não fosse entregue aos Judeus; mas agora meu Reino não é daqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 37, 'Disse-lhe pois Pilatos: Logo tu és Rei? Respondeu Jesus: Tu dizes que eu sou Rei. Para isto eu nasci, e para isto vim ao mundo: para dar testemunho à verdade. Todo aquele que é da verdade ouve minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 38, 'Disse-lhe Pilatos: O que é a verdade? E havendo dito isto, voltou a sair aos Judeus, e disse-lhes: Nenhum crime acho nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 39, 'Mas vós tendes por costume que eu vos solte um pela páscoa. Quereis pois que vos solte ao Rei dos Judeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 18, 40, 'Voltaram pois todos a clamar, dizendo: Não a este, mas a Barrabás!E Barrabás era um ladrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 1, 'Então Pilatos tomou a Jesus, e [o] açoitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 2, 'E trançando os soldados uma coroa de espinhos, puseram-na sobre sua cabeça, e o vestiram de uma roupa vermelha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 3, 'E diziam: Tenhas alegria, Rei dos Judeus! E davam-lhe bofetadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 4, 'Saiu pois Pilatos outra vez fora, e disse-lhes: Eis que eu o trago para fora [até] vós, para que saibais que nenhum crime acho nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 5, 'Jesus foi pois trazido para fora, levando a coroa de espinhos, e a roupa vermelha-roxa. E [Pilatos] disse-lhes: Eis aqui o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 6, 'Quando então os chefes dos sacerdotes e os trabalhadores o viram, eles clamaram, dizendo: Crucifica [-o] ! Crucifica [-o] ! Disse-lhes Pilatos: Tomai-o vós, e crucificai [-o] ; porque eu nenhum crime acho nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 7, 'Responderam-lhe os Judeus: Nós temos Lei, e segundo nossa Lei ele deve morrer, porque se fez Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 8, 'Quando pois Pilatos ouviu esta palavra, ficou mais atemorizado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 9, 'E entrou outra vez no tribunal, e disse a Jesus: De onde és tu? Mas Jesus não lhe deu resposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 10, 'Disse-lhe pois Pilatos: Não falas comigo? Não sabes que tenho poder para te crucificar, e tenho poder para te soltar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 11, 'Respondeu Jesus: Nenhum poder terias contra mim, se não te fosse dado de cima; portanto o que me entregou a ti tem maior pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 12, 'Desde então Pilatos procurava soltá-lo; mas os Judeus clamavam, dizendo: Se soltas a este, não és amigo de César; qualquer que se faz Rei, contradiz a César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 13, 'Então Pilatos, ouvindo este dito, levou fora a Jesus, e sentou-se no tribunal, no lugar chamado Litóstrotos, [ou pavimento] ,e em hebraico Gabatá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 14, 'E era a preparação da páscoa, e quase à hora sexta, e disse aos Judeus: Eis aqui vosso Rei!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 15, 'Mas eles bradaram: Tira, tira, crucifica-o! Disse-lhes Pilatos: Crucificarei a vosso Rei?Responderam os chefes dos sacerdotes: Não temos [outro] rei, a não ser César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 16, 'Então o entregou a eles, para que fosse crucificado. E tomaram a Jesus, e levaram [-no] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 17, 'E levando ele sua cruz, saiu para o [lugar] chamado a Caveira, que em hebraico se chama Gólgota.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 18, 'Onde o crucificaram, e com ele outros dois, um de cada lado, e a Jesus no meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 19, 'E Pilatos também escreveu um título, e o pôs encima da cruz, e estava [nele] escrito: JESUS NAZARENO, REI DOS JUDEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 20, 'Leram pois muitos dos Judeus este título; porque o lugar onde Jesus estava crucificado era perto da cidade; e estava escrito em hebraico, em grego, [e] em latim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 21, 'Diziam pois os chefes dos sacerdotes dos judeus a Pilatos: Não escrevas: Rei dos Judeus, mas que disse: Sou Rei dos Judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 22, 'Respondeu Pilatos: O que escrevi, escrevi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 23, 'Havendo pois os soldados crucificado a Jesus, tomaram suas roupas, e fizeram quatro partes, para cada soldado uma parte, e a túnica. E era a túnica sem costura, toda tecida desde cima [até baixo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 24, 'Disseram pois uns aos outros: Não a partamos, mas lancemos sortes sobre ela, de quem será; para que se cumprisse a Escritura, que diz: Entre si partiram minhas roupas, e sobre minha veste lançaram sortes. Os soldados, pois, fizeram isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 25, 'E estavam junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, Maria [mulher] de Cleofas, e Maria Madalena.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 26, 'E vendo Jesus a [sua] mãe, e ao discípulo a quem amava, que ali estava, disse a sua mãe: Mulher, eis aí teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 27, 'Depois disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua [casa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 28, 'Depois disto, sabendo Jesus que já todas as coisas estavam feitas, para que a Escritura se cumprisse, ele disse: Tenho sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 29, 'Estava pois ali um vaso cheio de vinagre, e encheram uma esponja de vinagre, e envolvendo-a com hissopo, levaram-na a sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 30, 'Quando pois Jesus tomou o vinagre, disse: Está consumado; e abaixando a cabeça, deu o Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 31, 'Os Judeus pois, para que os corpos não ficassem no sábado na cruz, pois era a preparação (porque era o grande dia do Sábado), suplicaram a Pilatos que as pernas deles fossem quebradas, e fossem tirados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 32, 'Vieram pois os soldados, e na verdade quebraram as pernas do primeiro, e do outro, que fora crucificado com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 33, 'Mas vindo a Jesus, [e] vendo-o já morto, não quebraram as suas pernas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 34, 'Mas um dos soldados lhe furou com uma lança o lado, e logo saiu sangue e água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 35, 'E o que viu isto, o testemunhou; e seu testemunho é verdadeiro, e sabe que é verdade o que diz, para que vós também creiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 36, 'Porque estas coisas aconteceram para que se cumprisse a Escritura [que diz] : Osso dele não será quebrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 37, 'E além disso, outra Escritura diz: Verão [aquele] a quem perfuraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 38, 'E depois José de Arimateia, (que era discípulo de Jesus, porém oculto por medo dos Judeus) suplicou a Pilatos que pudesse tirar o corpo de Jesus; e Pilatos permitiu. Veio pois e tirou o corpo de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 39, 'E veio também Nicodemos, (aquele que antes de noite tinha vindo a Jesus) trazendo um composto de mirra e aloés, de quase cem arráteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 40, 'Tomaram pois o corpo de Jesus, e o envolveram em lençóis com as especiarias, como é costume dos judeus sepultarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 41, 'E havia um jardim naquele lugar onde fora crucificado; e no jardim [havia] um sepulcro novo, em que ainda nunca alguém havia sido posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 19, 42, 'Ali pois (por causa da preparação [da páscoa] dos Judeus, e porque aquele sepulcro estava perto) puseram a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 1, 'E no primeiro [dia] da semana Maria Madalena veio de madrugada, sendo ainda escuro, ao sepulcro; e viu a pedra já tirada do sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 2, 'Correu pois, e veio a Simão Pedro, e ao outro discípulo a quem Jesus amava, e disse-lhes: Tomaram o Senhor do sepulcro, e não sabemos onde o puseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 3, 'Pedro saiu pois e o outro discípulo [também] ,e vieram ao sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 4, 'E corriam estes dois juntos: e o outro discípulo correu adiante mais depressa que Pedro, e chegou primeiro ao sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 5, 'E abaixando-se, viu estar os lençóis; entretanto não entrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 6, 'Chegou pois Simão Pedro seguindo-o, e entrou no sepulcro, e viu estar os lençóis [ali] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 7, 'E o lenço que fora [posto] sobre sua cabeça, não [o viu] estar com os lençóis, mas [estava] dobrado em um lugar à parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 8, 'Então pois entrou também o outro discípulo, que primeiro chegara ao sepulcro, e viu, e creu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 9, 'Porque ainda não sabiam a Escritura, que era necessário que ressuscitasse dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 10, 'Voltaram pois os Discípulos para [a casa] deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 11, 'E Maria estava fora chorando junto ao sepulcro. Estando ela pois chorando, abaixou-se para [ver] o sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 12, 'E viu a dois anjos [vestidos] de branco, sentados um à cabeceira, e o outro aos pés, onde estava posto o corpo de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 13, 'E disseram-lhe eles: Mulher, por que choras? Disse-lhes ela: Porque levaram a meu Senhor, e não sei onde o puseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 14, 'E havendo dito isto, virou-se para trás, e viu Jesus em pé, e não sabia que era Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 15, 'Disse-lhe Jesus: Mulher, por que choras? A quem buscas? Ela, pensando que era o jardineiro, disse-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 16, 'Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe: Rabôni! (que quer dizer Mestre).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 17, 'Disse-lhe Jesus: Não me toques; porque ainda não subi para o meu Pai; porém vai a meus irmãos, e dize- lhes: Subo para meu Pai, e para vosso Pai; [para] meu Deus, e [para] vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 18, 'Veio Maria Madalena, e anunciou aos discípulos, que vira ao Senhor, e [que] estas coisas lhe dissera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 19, 'Vinda pois já a tarde, o primeiro dia da semana, e fechadas as portas onde os Discípulos, por medo dos judeus, tinham se reunido, veio Jesus, e pôs-se no meio [deles] ,e disse-lhes: Tenhais paz!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 20, 'E dizendo isto, mostrou-lhes suas mãos, e [seu] lado. Então os discípulos se alegraram, vendo ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 21, 'Disse-lhes pois Jesus outra vez: Tenhais Paz! Como o Pai me enviou, assim eu vos envio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 22, 'E havendo dito isto, soprou [sobre eles] ,e disse-lhes: Recebei o Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 23, 'A quem quer que perdoardes os pecados, lhes são perdoados; [e] a quem quer que vós retiverdes [os pecados] ,[lhes] são retidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 24, 'E a Tomé, um dos doze, chamado o Dídimo, não estava com eles, quando Jesus veio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 25, 'Disseram-lhe pois os outros discípulos: Vimos ao Senhor. Porém ele lhes disse: Se em suas mãos não vir o sinal dos cravos, e não pôr meu dedo no lugar dos cravos, e não pôr minha mão em seu lado, em maneira nenhuma crerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 26, 'E oito dias depois, estavam os discípulos outra vez dentro, [e] com eles Tomé; e veio Jesus, fechadas já as portas, e pôs-se no meio, e disse: Tenhais paz!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 27, 'Depois disse a Tomé: Põe teu dedo aqui, e vê minhas mãos; e chega tua mão, e toca-a em meu lado; e não sejas incrédulo, mas sim crente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 28, 'E respondeu Tomé e disse-lhe: Senhor meu, e Deus meu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 29, 'Disse-lhe Jesus: Porque me viste, Tomé, creste; bem-aventurados aqueles que não virem, e crerem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 30, 'Jesus fez também ainda muitos outros sinais ainda em presença de seus discípulos, que neste livro não estão escritos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 20, 31, 'Porém estes estão escritos, para que creiais que Jesus é o Cristo, o Filho de Deus; e para que crendo, tenhais vida em seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 1, 'Depois disto Jesus se manifestou outra vez aos discípulos, junto ao mar de Tibérias; e manifestou [-se] assim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 2, 'Estavam juntos Simão Pedro, e Tomé (chamado o Dídimo), e Natanael (o de Caná de Galileia), e os [filhos] de Zebedeu, e outros dois de seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 3, 'Disse-lhes Simão Pedro: Vou pescar. Dizem-lhe eles: Também nós vamos contigo. Foram, e subiram logo no barco; e aquela noite nada pescaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 4, 'E fazendo-se já manhã, Jesus se pôs na praia; porém os discípulos não sabiam que era Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 5, 'Então Jesus lhes disse: Filhinhos, tendes [algo] para comer? Responderam-lhe: Não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 6, 'E ele lhes disse: Lançai a rede do lado direito do barco, e achareis. Lançaram-na pois, e já não a podiam tirar pela multidão dos peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 7, 'Disse pois aquele discípulo, a quem Jesus amava, a Pedro: É o Senhor! Ouvindo pois Simão Pedro que era o Senhor, vestiu-se com a roupa, (porque estava nu), e lançou-se ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 8, 'E os outros discípulos vieram com o barquinho (porque não estavam longe da terra, mas sim a cerca de duzentos côvados) trazendo a rede de peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 9, 'Quando pois desceram à terra, viram já as brasas postas, e um peixe posto nelas, e mais pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 10, 'Disse-lhes Jesus: Trazei dos peixes que pescastes agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 11, 'Simão Pedro subiu, e puxou a rede para a terra, cheia de cento e cinquenta e três grandes peixes; e sendo tantos, a rede não se rompeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 12, 'Disse-lhes Jesus: Vinde, jantai. E nenhum dos discípulos ousava lhe perguntar: Tu quem és? sabendo que era o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 13, 'Então Jesus veio, e tomou o pão, e deu-o a eles; e da mesma maneira o peixe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 14, 'E esta era já a terceira vez que Jesus se manifestou a seus discípulos, depois de haver ressuscitado dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 15, 'Havendo eles pois já jantado, disse Jesus a Simão Pedro: Simão [filho] de Jonas, tu me amas mais do que estes [outros] ? Disse-lhes ele: Sim, Senhor, tu sabes que te amo. Disse-lhe: Alimenta meus cordeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 16, 'Voltou a lhe a dizer a segunda vez: Simão, [filho] de Jonas, tu me amas? Disse-lhe: Sim, Senhor, tu sabes que te amo. Disse-lhe: Apascenta minhas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 17, 'Disse-lhe a terceira vez: Simão, [filho] de Jonas, tu me amas? Entristeceu-se Pedro de que já pela terceira vez lhe dissesse: Tu me amas? E disse-lhe: Senhor, tu sabes todas as coisas, tu sabes que eu te amo. Disse-lhe Jesus: Alimenta minhas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 18, 'Em verdade, em verdade te digo, que quando eras mais jovem, tu mesmo te vestias, e andava por onde querias; mas quando fores já velho, estenderás tuas mãos, e outro te vestirá, e te levará para onde tu não queres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 19, 'E disse isto, fazendo entender que [Pedro] glorificaria a Deus com [sua] morte. E tendo dito isto, [Jesus] lhe disse: Segue-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 20, 'E virando-se Pedro, viu que [o] seguia aquele discípulo a quem Jesus amava, o que também na ceia se recostara a seu peito, e dissera: Senhor, quem é o que te trairá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 21, 'Vendo Pedro a este, disse a Jesus: Senhor, e este, que [lhe acontecerá] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 22, 'Disse-lhe Jesus: Se eu quero que ele fique até que eu venha, que te importa? Segue-me tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 23, 'Saiu, pois, esta conversa entre os irmãos, que aquele discípulo não morreria. Contudo Jesus não lhe disse que não morreria, mas sim: Se eu quero que ele fique até que eu venha, que te importa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 24, 'Este é o discípulo que testemunha destas coisas, e estas coisas escreveu; e sabemos que seu testemunho é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 21, 25, 'Ainda há, porém, muitas outras coisas que Jesus fez, que se sobre cada uma delas se escrevessem, penso que nem mesmo o mundo poderia caber os livros escritos. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 1, 'Eu fiz o primeiro livro, ó Teófilo, sobre todas as coisas que Jesus começou, tanto a fazer como a ensinar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 2, 'Até o dia em que ele foi recebido acima, depois de pelo Espírito Santo ter dado mandamentos aos apóstolos que tinha escolhido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 3, 'Aos quais também, depois de ter sofrido, apresentou-se vivo com muitas evidências; sendo visto por eles durante quarenta dias, e falando [-lhes] das coisas relativas ao reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 4, 'E, reunindo-os, mandou-lhes que não saíssem de Jerusalém, mas que esperassem a promessa do Pai que (disse ele) de mim ouvistes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 5, 'Porque João batizou com água, mas vós sereis batizados com o Espírito Santo, não muitos dias depois destes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 6, 'Então aqueles que tinham se reunido lhe perguntaram, dizendo: Senhor, tu restaurarás neste tempo o Reino a Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 7, 'E ele lhes disse: Não pertence a vós saber os tempos ou estações que o Pai pôs em sua própria autoridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 8, 'Mas vós recebereis poder do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último [lugar] da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 9, 'E tendo ele dito estas coisas, enquanto eles o viam, ele foi levantado acima, e uma nuvem o tirou dos olhos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 10, 'E enquanto eles estavam com os olhos fixos ao céu, depois dele ter ido, eis que dois homens de roupas brancas se puseram junto a eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 11, 'Os quais também disseram: Homens galileus, por que estais olhando para o céu? Este Jesus, que foi tomado de vós acima ao céu, assim virá, da maneira como o vistes ir ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 12, 'Então eles voltaram a Jerusalém do monte que se chama das Oliveiras, o qual está perto de Jerusalém [à distância] de um caminho de sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 13, 'E ao entrarem, subiram ao cômodo superior, onde ficaram Pedro, Tiago, João, André, Filipe, Tomé, Bartolomeu, Mateus, Tiago [filho] de Alfeu, Simão Zelote e Judas [irmão] de Tiago.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 14, 'Todos estes perseveravam concordando em orações, e petições, com as mulheres, com Maria a mãe de Jesus, e com os irmãos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 15, 'E em [algum d] aqueles dias, havendo uma multidão reunida de cerca de cento e vinte pessoas, Pedro se levantou no meio dos discípulos e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 16, 'Homens irmãos, era necessário que se cumprisse a Escritura, que o Espírito Santo, por meio da boca de Davi, predisse quanto a Judas, que foi o guia daqueles que prenderam a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 17, 'Porque ele foi contado conosco, e obteve uma porção neste ministério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 18, 'Este pois, adquiriu um campo por meio do pagamento da maldade, e tendo caído de cabeça para baixo, partiu-se ao meio, e todos os seus órgãos internos caíram para fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 19, 'E [isso] foi conhecido por todos os que habitam em Jerusalém, de maneira que aquele campo se chama em sua própria língua Aceldama, isto é, campo de sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 20, 'Porque está escrito no livro dos Salmos: Sua habitação se faça deserta, e não haja quem nela habite; e outro tome seu trabalho de supervisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 21, 'Portanto é necessário, que dos homens que nos acompanharam todo o tempo em que o Senhor Jesus entrava e saía conosco,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 22, 'Começando desde o batismo de João, até o dia em que [diante] de nós ele foi recebido acima, se faça um destes testemunha conosco de sua ressurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 23, 'E apresentaram dois: a José, chamado Barsabás, que tinha por sobrenome [o] Justo; e a Matias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 24, 'E orando, disseram: Tu, Senhor, conhecedor dos corações de todos, mostra a qual destes dois tu tens escolhido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 25, 'Para que ele tome parte deste ministério e apostolado, do qual Judas se desviou para ir a seu próprio lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 1, 26, 'E lançaram-lhes as sortes; e caiu a sorte sobre Matias. E ele [passou] a ser contado junto com os onze apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 1, 'E ao se cumprir o dia de Pentecostes, estavam todos concordando no mesmo lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 2, 'E de repente houve um ruído do céu, como de um vento forte [e] violento, e encheu toda a casa onde eles estavam sentados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 3, 'E foram vistas por eles línguas repartidas como que de fogo, e se pôs sobre cada um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 4, 'E eles foram todos cheios do Espírito Santo, e começaram a falar em outras línguas, conforme o Espírito lhes dava a discursarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 5, 'E havia judeus que estavam morando em Jerusalém, homens devotos, de toda nação abaixo do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 6, 'E acontecendo esta voz, ajuntou-se a multidão; e ela estava confusa, porque cada um os ouvia falar em sua própria língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 7, 'E todos estavam admirados, e se maravilhavam, dizendo uns aos outros: Ora, estes que estão falando, não são todos eles galileus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 8, 'E como nós ouvimos cada um [deles] em nossa própria língua, na qual nascemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 9, 'Partos, Medos, Elamitas, os habitantes da Mesopotâmia, da Judeia, Capadócia, Ponto, Ásia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 10, 'Frígia, Panfília, Egito e regiões da Líbia perto de Cirene, e romanos estrangeiros, tanto judeus como prosélitos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 11, 'Cretenses e Árabes, os ouvimos em nossas próprias línguas eles falarem das grandezas de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 12, 'E todos estavam admirados e confusos, dizendo uns aos outros: O que isso quer dizer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 13, 'E outros, ridicularizando, diziam: Eles estão cheios de vinho doce.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 14, 'Mas Pedro, pondo-se de pé com os onze, levantou sua voz, e lhes falou: Homens judeus, e todos os que habitais em Jerusalém, seja isto conhecido, e ouvi minhas palavras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 15, 'Porque estes não estão bêbados, como vós pensais, sendo [ainda] a terceira hora do dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 16, 'Mas isto é o que foi dito por meio do profeta Joel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 17, 'E será nos últimos dias, diz Deus, que: Eu derramarei do meu Espírito sobre toda carne, e vossos filhos e filhas profetizarão, e vossos rapazes terão visões, e vossos velhos sonharão sonhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 18, 'E também sobre meus servos e sobre minhas servas, naqueles dias eu derramarei do meu Espírito, e profetizarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 19, 'E darei milagres acima no céu, e sinais abaixo na terra; sangue, fogo, e vapor de fumaça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 20, 'O sol se converterá em trevas, e a lua em sangue, antes que venha o grande e notório dia do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 21, 'E será que todo aquele que chamar ao nome do Senhor será salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 22, 'Homens israelitas, ouvi estas palavras: Jesus o nazareno, homem aprovado por Deus entre vós, com maravilhas, milagres e sinais, que Deus fez por meio dele no meio de vós, assim como vós mesmos também sabeis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 23, 'Este, sendo entregue pelo determinado conselho e conhecimento prévio de Deus, sendo tomando, pelas mãos de injustos [o] crucificastes e matastes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 24, 'Ao qual Deus ressuscitou, tendo soltado as dores da morte; porque não era possível ele ser retido por ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 25, 'Porque Davi diz sobre ele: Eu sempre via ao Senhor diante de mim, porque ele está à minha direita, para que eu não seja abalado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 26, 'Por isso meu coração está contente, e minha língua se alegra, e até mesmo minha carne repousará em esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 27, 'Pois tu não abandonarás minha alma no Xeol, nem permitirás que o teu santo veja a degradação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 28, 'Tu tens me feito conhecer os caminhos da vida; tu me encherás de alegria com tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 29, 'Homens irmãos, é lícito eu vos dizer abertamente sobre o patriarca Davi, que morreu, e foi sepultado, e a sepultura dele está conosco até o dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 30, 'Portanto, sendo ele profeta, e sabendo que Deus tinha lhe prometido com juramento que, da sua descendência segundo a carne, levantaria ao Cristo para se sentar no seu trono;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 31, 'Vendo [-o] com antecedência, falou da ressurreição do Cristo, que a sua alma não foi abandonada no Xeol, nem a sua carne viu a degradação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 32, 'A este Jesus Deus ressuscitou; do qual todos nós somos testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 33, 'Portanto, tendo sido exaltado à direita de Deus, e recebido do Pai a promessa do Espírito Santo, derramou isto que agora estais vendo e ouvindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 34, 'Porque Davi não subiu aos céus; mas sim, ele diz: Disse o Senhor a meu Senhor: Senta-te à minha direita,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 35, 'Até que eu ponha teus inimigos por escabelo de teus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 36, 'Saiba então com certeza toda a casa de Israel, que Deus o fez Senhor e Cristo a este Jesus, que vós crucificastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 37, 'E eles, ao ouvirem [estas coisas] , foram afligidos como que perfurados de coração, e disseram a Pedro, e aos outros apóstolos: Que faremos, homens irmãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 38, 'E Pedro lhes disse: Arrependei-vos, e batize-se cada um de vós no nome de Jesus Cristo, para perdão dos pecados; e vós recebereis o dom do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 39, 'Porque a promessa é para vós, e para vossos filhos, e para todos que [ainda] estão longe, a tantos quantos Deus, nosso Senhor, chamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 40, 'E com muitas outras palavras ele dava testemunho, e exortava, dizendo: Salvai-vos desta geração perversa!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 41, 'Então os que receberam a palavra dele de boa vontade foram batizados; e foram adicionados naquele dia quase três mil almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 42, 'E eles perseveravam na doutrina dos apóstolos, na comunhão, no partir do pão, e nas orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 43, 'E houve temor em toda alma; e muitos milagres e sinais foram feitos pelos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 44, 'E todos os que criam estavam juntos, e tinham todas as coisas em comum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 45, 'E eles vendiam [suas] propriedades e bens, e as repartiam com todos, conforme a necessidade que cada um tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 46, 'E perseverando a cada dia em concordância no Templo, e partindo o pão de casa em casa, comiam juntos com alegria e sinceridade de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 2, 47, 'Louvando a Deus, e tendo graça, [sendo do agrado] de todo o povo. E a cada dia o Senhor acrescentava à igreja aqueles que estavam sendo salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 1, 'E Pedro e João estavam subindo juntos para o Templo à hora da oração (a nona [hora] );'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 2, 'E um certo homem estava sendo trazido, que era aleijado desde o ventre de sua mãe, ao qual todo dia colocavam à porta do Templo, chamada [Porta] Formosa, para pedir esmola aos que entravam no Templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 3, 'O qual, ao ver Pedro e João perto de entrarem no Templo, ele [lhes] pediu uma esmola.')
